      projectIdentity: deps.projectIdentity,
      lastRunAt: readLastRunAt(deps.db, deps.projectIdentity, d.config.task),
      retrospectiveWatermarkMs: readRetrospectiveWatermark(deps.db, deps.projectIdentity, d.config.task),
